// liste à plat : { c: catégorie, t: vrai/faux, s: affirmation, e: explication }
const ty = (x) => x.replace(/ ([?!:;»])/g, "\u00a0$1").replace(/« /g, "«\u00a0").replace(/(\d) (?=\d{3}\b)/g, "$1\u00a0");
export const VF_LIST = VF_CATS.flatMap((c) => VF[c].map(([t, s, e]) => ({ c, t: !!t, s: ty(s), e: ty(e) })));
